                                                                                                                                                                                                                  
  CREATE TABLE "TENANT_EVENT_REVIEW_RULE_CONFIG"                                                                                                                                                       
   (	"EVENT_REVIEW_RULE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"RULE_NAME" NVARCHAR2(256) NOT NULL ENABLE,                                                                                                                                                                      
	"EXT_ORG_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                             
	"IS_ENABLE" NUMBER DEFAULT 1,                                                                                                                                                                                    
	"IS_STOP_LINE" VARCHAR2(16) NOT NULL ENABLE,                                                                                                                                                                     
	"IS_KEY_PROCESS" VARCHAR2(16) NOT NULL ENABLE,                                                                                                                                                                   
	"EVENT_TIME" NUMBER NOT NULL ENABLE,                                                                                                                                                                             
	"TENANT_ID" NUMBER DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                    
	"CREATED_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                             
	"CREATE_BY" NUMBER NOT NULL ENABLE,                                                                                                                                                                              
	"UPDATED_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                             
	"UPDATE_BY" NUMBER NOT NULL ENABLE,                                                                                                                                                                              
	"DEL_FLAG" NUMBER DEFAULT 0,                                                                                                                                                                                     
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                    
	 CHECK (IS_STOP_LINE IN ('TRUE', 'FALSE')) ENABLE,                                                                                                                                                               
	 CHECK ("IS_KEY_PROCESS" = 'TRUE' OR "IS_KEY_PROCESS" = 'FALSE') ENABLE,                                                                                                                                         
	 CHECK (DEL_FLAG IN (0, 1)) ENABLE,                                                                                                                                                                              
	 PRIMARY KEY ("EVENT_REVIEW_RULE_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                            
	 CHECK (IS_ENABLE IN (0, 1)) ENABLE                                                                                                                                                                              
   ) ;                                                                                                                                                                                                            

